  9→type SubExploitation = {
 10→    id: number;
 11→    species: string;
 12→    exploitation_type: string;
 13→    zootechnical_classification: string;
 14→    productive_system: string;
 15→    current_capacity: number;
 16→    max_capacity: number;
 17→    sustainability: string | null;
 18→    self_consumption: boolean;
 19→    census_date: string | null;
 20→    status: string | null;
 21→};
 22→
 23→type Semaforo = {
 24→    capacity: 'ok' | 'warning' | 'danger';
 25→    alerts: number;
 26→    pending: number;
 27→};
 28→
 29→type Props = {
 30→    subExploitation: SubExploitation;
 31→    animalsCount: number;
 32→    semaforo: Semaforo;
 33→};
 34→
 35→const speciesLabels: Record<string, string> = {
 36→    bovine: 'Bovino',
 37→    ovine: 'Ovino',
 38→    caprine: 'Caprino',
 39→    porcine: 'Porcino',
 40→    equine: 'Equino',
 41→};
 42→
 43→const speciesHeaderColors: Record<string, string> = {
 44→    bovine: 'bg-[#E53935]',
 45→    ovine: 'bg-black',
 46→    caprine: 'bg-black',
 47→    porcine: 'bg-neutral-700',
 48→    equine: 'bg-amber-900',
 49→};
