 51→function getCapacityGroup(maxCapacity: number): string {
 52→    if (maxCapacity <= 10) return 'Grupo I (1-10 UGM)';
 53→    if (maxCapacity <= 40) return 'Grupo II (11-40 UGM)';
 54→    if (maxCapacity <= 100) return 'Grupo III (41-100 UGM)';
 55→    return 'Grupo IV (>100 UGM)';
 56→}
 57→
 58→function SemaforoIndicator({ status, alerts, pending }: Semaforo) {
 59→    const capacityConfig = {
 60→        ok: { bg: 'bg-[#2E7D32]', text: 'text-white', icon: CheckCircle2, label: 'Capacidad' },
 61→        warning: { bg: 'bg-[#F9A825]', text: 'text-black', icon: TriangleAlert, label: 'Capacidad' },
 62→        danger: { bg: 'bg-[#E53935]', text: 'text-white', icon: Timer, label: 'Capacidad' },
 63→    };
 64→
 65→    const cap = capacityConfig[status];
 66→    const CapIcon = cap.icon;
 67→
 68→    return (
 69→        <div className="flex gap-2">
 70→            <div className={`flex flex-1 flex-col items-center gap-1 rounded-sm ${cap.bg} px-3 py-3`}>
 71→                <CapIcon className={`size-5 ${cap.text}`} />
 72→                <span className={`text-[11px] font-semibold ${cap.text}`}>{cap.label}</span>
 73→            </div>
 74→            <div className="flex flex-1 flex-col items-center gap-1 rounded-sm bg-[#F9A825] px-3 py-3">
 75→                <TriangleAlert className="size-5 text-black" />
 76→                <span className="text-[11px] font-semibold text-black">
 77→                    {alerts} {alerts === 1 ? 'Alerta' : 'Alertas'}
 78→                </span>
 79→            </div>
 80→            <div className="flex flex-1 flex-col items-center gap-1 rounded-sm bg-[#E53935] px-3 py-3">
 81→                <Timer className="size-5 text-white" />
 82→                <span className="text-[11px] font-semibold text-white">
 83→                    {pending} {pending === 1 ? 'Pendiente' : 'Pendientes'}
 84→                </span>
 85→            </div>
 86→        </div>
 87→    );
 88→}
 89→
 90→function DetailRow({ label, value, valueColor }: { label: string; value: string; valueColor?: string }) {
 91→    return (
 92→        <div className="flex items-center justify-between px-4 py-3.5">
 93→            <span className="text-[13px] font-medium text-[#757575]">{label}</span>
 94→            <span className={`text-[13px] font-bold ${valueColor ?? 'text-black'}`}>{value}</span>
 95→        </div>
 96→    );
 97→}
 98→
 99→function DetailRowWithSub({ label, value, sub }: { label: string; value: string; sub: string }) {
100→    return (
101→        <div className="flex items-center justify-between px-4 py-3.5">
102→            <span className="text-[13px] font-medium text-[#757575]">{label}</span>
103→            <div className="flex flex-col items-end gap-0.5">
104→                <span className="text-[13px] font-bold text-black">{value}</span>
105→                <span className="text-[11px] font-medium text-[#BDBDBD]">{sub}</span>
106→            </div>
107→        </div>
108→    );
109→}
110→
111→function ActionButton({ icon: Icon, label, href }: { icon: React.ComponentType<{ className?: string }>; label: string; href?: string }) {
112→    if (href) {
113→        return (
114→            <Link href={href} className="flex flex-1 flex-col items-center gap-2 border-2 border-black p-4">
115→                <Icon className="size-6 text-[#E53935]" />
116→                <span className="text-center text-[13px] font-semibold">{label}</span>
117→            </Link>
118→        );
119→    }
120→
121→    return (
122→        <button className="flex flex-1 cursor-default opacity-50">
123→            <div className="flex flex-1 flex-col items-center gap-2 border-2 border-black p-4">
124→                <Icon className="size-6 text-[#E53935]" />
125→                <span className="text-center text-[13px] font-semibold">{label}</span>
126→            </div>
127→        </button>
128→    );
129→}
