131→export default function SubExploitationShow({ subExploitation, animalsCount, semaforo }: Props) {
132→    const breadcrumbs: BreadcrumbItem[] = [
133→        { title: 'Mi Explotación', href: dashboard() },
134→        {
135→            title: `${speciesLabels[subExploitation.species] ?? subExploitation.species} · ${subExploitation.zootechnical_classification}`,
136→            href: subExploitationShow.url(subExploitation.id),
137→        },
138→    ];
139→
140→    const label = speciesLabels[subExploitation.species] ?? subExploitation.species;
141→    const headerColor = speciesHeaderColors[subExploitation.species] ?? 'bg-black';
142→    const sustainabilityColor = subExploitation.sustainability?.toLowerCase() === 'ecológico' ? 'text-[#2E7D32]' : undefined;
143→    const censusDate = subExploitation.census_date
144→        ? new Date(subExploitation.census_date).toLocaleDateString('es-ES', { day: '2-digit', month: '2-digit', year: 'numeric' })
145→        : null;
146→
147→    return (
148→        <AppLayout breadcrumbs={breadcrumbs}>
149→            <Head title={`${label} · ${subExploitation.zootechnical_classification}`} />
150→            <div className="flex flex-col gap-5 p-6">
151→                {/* Species Header Card */}
152→                <div className={`${headerColor} rounded-lg px-4 py-4 text-white`}>
153→                    <p className="text-lg font-bold">
154→                        {label} · {subExploitation.exploitation_type}
155→                    </p>
156→                    <p className="text-[13px] font-medium opacity-85">
157→                        {subExploitation.zootechnical_classification} · {subExploitation.productive_system}
158→                    </p>
159→                </div>
160→
161→                {/* Semáforo */}
162→                <SemaforoIndicator
163→                    status={semaforo.capacity}
164→                    alerts={semaforo.alerts}
165→                    pending={semaforo.pending}
166→                />
167→
168→                {/* Datos Zootécnicos */}
169→                <div className="overflow-hidden border-2 border-black">
170→                    <DetailRow
171→                        label="Clasificación zootécnica"
172→                        value={subExploitation.zootechnical_classification}
173→                    />
174→                    <div className="h-[2px] bg-black" />
175→                    <DetailRow
176→                        label="Capacidad productiva"
177→                        value={getCapacityGroup(subExploitation.max_capacity)}
178→                    />
179→                    <div className="h-[2px] bg-black" />
180→                    <DetailRow
181→                        label="Forma de cría"
182→                        value={subExploitation.sustainability ?? 'Convencional'}
183→                        valueColor={sustainabilityColor}
184→                    />
185→                    <div className="h-[2px] bg-black" />
186→                    <DetailRowWithSub
187→                        label="Censo actual"
188→                        value={`${animalsCount} animales`}
189→                        sub={censusDate ? `Actualizado: ${censusDate}` : ''}
190→                    />
191→                </div>
192→
193→                {/* Acciones Rápidas */}
194→                <div className="flex flex-col gap-3">
195→                    <span className="text-xs font-semibold tracking-[2px] text-[#757575]">
196→                        ACCIONES RÁPIDAS
197→                    </span>
198→                    <div className="flex gap-3">
199→                        <ActionButton icon={List} label="Ver animales" href={animalesIndex.url(subExploitation.id)} />
200→                        <ActionButton icon={FileText} label="Trámites" href="/normativa" />
201→                        <ActionButton icon={Syringe} label="Campañas" href="/normativa" />
202→                    </div>
203→                </div>
204→
205→                {/* CTA Buttons */}
206→                <Link
207→                    href="/nacimientos/crear"
208→                    className="flex items-center justify-center gap-2 bg-[#2E7D32] px-4 py-4 text-white"
209→                >
210→                    <Baby className="size-5" />
211→                    <span className="text-[15px] font-bold">Informar nacimiento</span>
212→                </Link>
213→
214→                <Link
215→                    href="/scanner"
216→                    className="flex items-center justify-center gap-2 bg-black px-4 py-4 text-white"
217→                >
218→                    <ScanLine className="size-5" />
219→                    <span className="text-[15px] font-bold">Escanear crotal (OCR)</span>
220→                </Link>
221→            </div>
222→        </AppLayout>
223→    );
224→}
