 3→namespace App\Http\Controllers;
 4→
 5→use App\Models\SubExploitation;
 6→use Inertia\Inertia;
 7→use Inertia\Response;
 8→
 9→class SubExploitationController extends Controller
10→{
11→    public function show(SubExploitation $subExploitation): Response
12→    {
13→        $subExploitation->load(['exploitation', 'animals']);
14→
15→        $animalsCount = $subExploitation->animals->count();
16→        $capacityRatio = $subExploitation->max_capacity > 0
17→            ? $subExploitation->current_capacity / $subExploitation->max_capacity
18→            : 0;
19→
20→        // Mocked semáforo indicators
21→        $capacityStatus = $capacityRatio > 0.8 ? 'danger' : ($capacityRatio > 0.6 ? 'warning' : 'ok');
22→        $alertsCount = rand(0, 3);
23→        $pendingCount = rand(0, 5);
24→
25→        return Inertia::render('subexplotaciones/show', [
26→            'subExploitation' => $subExploitation,
27→            'animalsCount' => $animalsCount,
28→            'semaforo' => [
29→                'capacity' => $capacityStatus,
30→                'alerts' => $alertsCount,
31→                'pending' => $pendingCount,
32→            ],
33→        ]);
34→    }
35→}
